package local.skyfamily;
import android.graphics.*;import android.view.*;import android.widget.*;import android.os.Handler;import android.media.MediaPlayer;import java.util.*;import java.io.*;import java.net.*;import java.util.concurrent.*;
final class FramePlayer extends FrameLayout {
 final GalleryActivity host;final ArrayList<GalleryActivity.Slide> slides;final Handler handler=new Handler();final ExecutorService loader=Executors.newSingleThreadExecutor();FrameLayout stage;LinearLayout overlay;TextView caption,status,play,mute;SeekBar seek;VideoView video;MediaPlayer media;File temporary;volatile HttpURLConnection connection;volatile int generation=0;volatile boolean closed=false;boolean playing,muted,ready=false;int index;float downX,downY;
 FramePlayer(GalleryActivity h,ArrayList<GalleryActivity.Slide> list,int i,boolean autoplay){super(h);host=h;slides=list;index=i;playing=autoplay;muted=h.prefs.getBoolean("gallery.mute",true);setBackgroundColor(android.graphics.Color.BLACK);stage=new FrameLayout(h);addView(stage,new FrameLayout.LayoutParams(-1,-1));caption=new TextView(h);caption.setTextColor(android.graphics.Color.WHITE);caption.setTextSize(16);caption.setPadding(h.dp(14),h.dp(12),h.dp(14),h.dp(12));caption.setBackgroundColor(0x99000000);FrameLayout.LayoutParams top=new FrameLayout.LayoutParams(-1,-2,Gravity.TOP);addView(caption,top);overlay=new LinearLayout(h);overlay.setOrientation(1);overlay.setPadding(h.dp(8),h.dp(8),h.dp(8),h.dp(8));overlay.setBackgroundColor(0xbb000000);FrameLayout.LayoutParams bottom=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);addView(overlay,bottom);status=new TextView(h);status.setTextColor(android.graphics.Color.WHITE);overlay.addView(status);seek=new SeekBar(h);overlay.addView(seek);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int value,boolean user){if(user&&video!=null&&ready)video.seekTo(value);}public void onStartTrackingTouch(SeekBar s){handler.removeCallbacks(hide);}public void onStopTrackingTouch(SeekBar s){controls();}});LinearLayout row=new LinearLayout(h);overlay.addView(row);control(row,"Previous",()->advance(-1));play=control(row,playing?"Pause":"Play",()->toggle());control(row,"Next",()->advance(1));mute=control(row,muted?"Unmute":"Mute",()->{muted=!muted;host.prefs.edit().putBoolean("gallery.mute",muted).apply();volume();mute.setText(muted?"Unmute":"Mute");controls();});control(row,"Exit",()->host.home());}
 TextView control(LinearLayout row,String label,Runnable action){TextView t=new TextView(host);t.setText(label);t.setTextSize(15);t.setTextColor(android.graphics.Color.WHITE);t.setGravity(Gravity.CENTER);t.setMinHeight(host.dp(50));row.addView(t,new LinearLayout.LayoutParams(0,-2,1));t.setOnClickListener(v->action.run());return t;}
 final Runnable hide=()->{if(playing&&!closed){overlay.setVisibility(GONE);caption.setVisibility(GONE);}};final Runnable advance=()->{if(playing&&!closed)advance(1);};
 final Runnable progress=new Runnable(){public void run(){if(closed)return;if(video!=null&&ready){seek.setMax(Math.max(1,video.getDuration()));seek.setProgress(video.getCurrentPosition());}handler.postDelayed(this,500);}};
 void controls(){overlay.setVisibility(VISIBLE);caption.setVisibility(VISIBLE);handler.removeCallbacks(hide);if(playing)handler.postDelayed(hide,3500);}
 void volume(){if(media!=null)try{media.setVolume(muted?0:1,muted?0:1);}catch(Exception ignored){}}
 void toggle(){playing=!playing;handler.removeCallbacks(advance);play.setText(playing?"Pause":"Play");if(video!=null&&ready){if(playing)video.start();else video.pause();}else if(playing&&ready)handler.postDelayed(advance,host.prefs.getInt("gallery.seconds",10)*1000L);controls();}
 void pause(){playing=false;handler.removeCallbacks(advance);handler.removeCallbacks(hide);if(video!=null&&ready)try{video.pause();}catch(Exception ignored){}play.setText("Play");controls();}
 void advance(int delta){if(closed)return;index=(index+delta+slides.size())%slides.size();show();}
 View.OnTouchListener gestures=new View.OnTouchListener(){public boolean onTouch(View v,MotionEvent e){if(e.getAction()==0){downX=e.getX();downY=e.getY();return true;}if(e.getAction()==1){float x=e.getX()-downX,y=e.getY()-downY;if(Math.abs(x)>host.dp(60)&&Math.abs(x)>Math.abs(y))advance(x<0?1:-1);else if(overlay.getVisibility()==VISIBLE){overlay.setVisibility(GONE);caption.setVisibility(GONE);}else controls();return true;}return true;}};
 void cancelMedia(){generation++;handler.removeCallbacks(advance);handler.removeCallbacks(progress);HttpURLConnection c=connection;if(c!=null)c.disconnect();connection=null;if(video!=null){video.stopPlayback();video=null;}media=null;if(temporary!=null){temporary.delete();temporary=null;}stage.removeAllViews();ready=false;}
 void show(){if(closed)return;cancelMedia();final int stamp=generation;GalleryActivity.Slide slide=slides.get(index);caption.setText((index+1)+" / "+slides.size()+"   "+slide.title);status.setText(slide.video?"Preparing video...":"Loading photo...");seek.setVisibility(slide.video?VISIBLE:GONE);play.setText(playing?"Pause":"Play");ImageView image=new ImageView(host);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setOnTouchListener(gestures);if(!slide.video)stage.addView(image,new FrameLayout.LayoutParams(-1,-1));else{video=new VideoView(host);video.setOnTouchListener(gestures);stage.addView(video,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));}controls();loader.submit(()->{File downloaded=null;try{if(slide.video){downloaded=downloadVideo(slide,stamp);final File file=downloaded;handler.post(()->{if(closed||generation!=stamp){file.delete();return;}temporary=file;video.setVideoPath(file.getAbsolutePath());video.setOnPreparedListener(mp->{if(closed||generation!=stamp)return;media=mp;ready=true;volume();status.setText("Swipe for previous/next. Tap to show controls.");if(playing)video.start();handler.post(progress);});video.setOnCompletionListener(mp->{if(playing)advance(1);});video.setOnErrorListener((mp,w,e)->{failure(stamp,"Video codec/playback unsupported on this frame");return true;});video.start();if(!playing)video.pause();});}else{byte[] bytes=slide.file!=null?host.read(slide.file):host.request(slide.address,"GET",null,slide.credential,20000000);if(closed||generation!=stamp)return;Bitmap bitmap=host.bitmap(bytes);if(bitmap==null)throw new IOException("Unsupported image format");handler.post(()->{if(closed||generation!=stamp)return;image.setImageBitmap(bitmap);ready=true;status.setText("Swipe for previous/next. Tap to show controls.");if(playing)handler.postDelayed(advance,host.prefs.getInt("gallery.seconds",10)*1000L);});}}catch(Exception e){if(downloaded!=null)downloaded.delete();handler.post(()->failure(stamp,"Unable to load media: "+e.getMessage()));}});}
 File downloadVideo(GalleryActivity.Slide slide,int stamp)throws Exception{File file=File.createTempFile("gallery-video-",".mp4",host.getCacheDir());HttpURLConnection c=(HttpURLConnection)new URL(slide.address).openConnection();connection=c;c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(25000);if(!slide.credential.isEmpty())c.setRequestProperty("Authorization","Bearer "+slide.credential);boolean success=false;try{int code=c.getResponseCode();if(code!=200)throw new IOException("HTTP "+code);try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(file)){byte[] b=new byte[32768];long bytes=0;int n;while((n=in.read(b))!=-1){if(closed||generation!=stamp)throw new IOException("Cancelled");bytes+=n;if(bytes>268435456L)throw new IOException("Video exceeds 256 MiB playback cache limit");out.write(b,0,n);}}success=true;return file;}finally{c.disconnect();if(connection==c)connection=null;if(!success)file.delete();}}
 void failure(int stamp,String message){if(closed||generation!=stamp)return;status.setText(message+" / use Next or Exit");controls();if(playing)handler.postDelayed(advance,3500);}
 void close(){if(closed)return;closed=true;cancelMedia();handler.removeCallbacksAndMessages(null);loader.shutdownNow();}
 protected void onDetachedFromWindow(){close();super.onDetachedFromWindow();}
}
